const crypto = require('crypto');

function getVar(name) {
  try {
    if (typeof $vars !== 'undefined' && $vars[name]) return $vars[name];
  } catch {}
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch {}
  return '';
}

const secret = getVar('N8N_WEBHOOK_SECRET');
const convexSiteUrl = getVar('CONVEX_SITE_URL').replace(/\/+$/, '');

if (!secret || !convexSiteUrl) {
  throw new Error('Missing N8N_WEBHOOK_SECRET or CONVEX_SITE_URL variable in n8n.');
}

const ts = Date.now();
const sigHex = crypto
  .createHmac('sha256', secret)
  .update(`${ts}.`)
  .digest('hex');

return [
  {
    json: {
      convexSiteUrl,
      signatureHeader: `t=${ts},v1=${sigHex}`,
    },
  },
];

const crypto = require('crypto');

function getVar(name) {
  try {
    if (typeof $vars !== 'undefined' && $vars[name]) return $vars[name];
  } catch {}
  try {
    if (typeof $env !== 'undefined' && $env[name]) return $env[name];
  } catch {}
  return '';
}

const secret = getVar('N8N_WEBHOOK_SECRET');
const convexSiteUrl = getVar('CONVEX_SITE_URL').replace(/\/+$/, '');

if (!secret || !convexSiteUrl) {
  throw new Error('Missing N8N_WEBHOOK_SECRET or CONVEX_SITE_URL variable in n8n.');
}

const response = $input.first()?.json || {};
const overdueLoans = Array.isArray(response.overdueLoans) ? response.overdueLoans : [];

if (overdueLoans.length === 0) {
  return [];
}

const todayKey = new Date().toISOString().slice(0, 10);
const fmtDate = (ms) => new Date(ms).toLocaleDateString('en-US', {
  month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC'
});

const results = [];

for (const loan of overdueLoans) {
  if (!loan.borrowerEmail) continue;

  const dueDateText = fmtDate(loan.endDate);
  const daysText = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
  const subject = `Friendly reminder: Please return ${loan.toolName}`;
  const message = `Hi ${loan.borrowerName}, your borrow window for ${loan.toolName} from ${loan.lenderName} ended on ${dueDateText} (${daysText} overdue). Please arrange a return soon!`;
  const summary = `Overdue reminder (${daysText} late) sent to ${loan.borrowerEmail}`;

  const writebackBody = {
    loanId: loan.loanId,
    workflow: 'overdue_reminder',
    event: 'loan.overdue_reminder',
    status: 'delivered',
    recipientEmail: loan.borrowerEmail,
    summary,
    idempotencyKey: `overdue_reminder:${loan.loanId}:${todayKey}`,
  };

  const rawWritebackBody = JSON.stringify(writebackBody);
  const ts = Date.now();
  const sigHex = crypto
    .createHmac('sha256', secret)
    .update(`${ts}.${rawWritebackBody}`)
    .digest('hex');

  results.push({
    json: {
      reminder: {
        loanId: loan.loanId,
        to: loan.borrowerEmail,
        borrowerName: loan.borrowerName,
        toolName: loan.toolName,
        daysOverdue: loan.daysOverdue,
        subject,
        message,
      },
      convexSiteUrl,
      rawWritebackBody,
      writebackSignature: `t=${ts},v1=${sigHex}`,
    },
  });
}

return results;

// Logged mock overdue reminder channel (swap/connect Email, Slack, or Discord here using n8n credentials)
for (const item of $input.all()) {
  const r = item.json.reminder;
  console.log('[LendLoop Overdue Reminder Sent]', JSON.stringify({
    loanId: r.loanId,
    to: r.to,
    subject: r.subject,
    message: r.message,
    daysOverdue: r.daysOverdue,
    sentAt: new Date().toISOString(),
  }));
}
return $input.all();
